SELECT CASE WHEN s.risk_reward_ratio IS NULL THEN 'NULL' WHEN s.risk_reward_ratio < 0.5 THEN '<0.5' WHEN s.risk_reward_ratio < 1 THEN '0.5-1' WHEN s.risk_reward_ratio < 2 THEN '1-2' ELSE '>=2' END AS rr_bucket, COUNT(*) AS n, SUM(p.status='STOPPED') AS n_stopped, SUM(p.realized_pnl<0) AS losses, ROUND(SUM(p.realized_pnl),4) AS gross_pnl, ROUND(SUM(p.realized_pnl-0.001*p.quantity*(p.entry_price+p.exit_price)),4) AS net_010, ROUND(SUM(p.realized_pnl-0.00075*p.quantity*(p.entry_price+p.exit_price)),4) AS net_0075 FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id=p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) GROUP BY rr_bucket ORDER BY rr_bucket LIMIT 10;
SELECT CASE WHEN m.entry_quality_score IS NULL THEN 'NO_WMP' WHEN m.entry_quality_score < 50 THEN '<50' WHEN m.entry_quality_score = 50 THEN '=50' WHEN m.entry_quality_score < 55 THEN '51-54' WHEN m.entry_quality_score < 70 THEN '55-69' WHEN m.entry_quality_score < 85 THEN '70-84' ELSE '85+' END AS eq_bucket, COUNT(*) AS n, SUM(p.status='STOPPED') AS n_stopped, SUM(p.realized_pnl<0) AS losses, ROUND(SUM(p.realized_pnl),4) AS gross_pnl, ROUND(SUM(p.realized_pnl-0.001*p.quantity*(p.entry_price+p.exit_price)),4) AS net_010, ROUND(SUM(p.realized_pnl-0.00075*p.quantity*(p.entry_price+p.exit_price)),4) AS net_0075 FROM crypto_ai.paper_position p LEFT JOIN crypto_ai.wallet_managed_position m ON m.entry_signal_id=p.signal_id WHERE p.status IN ('CLOSED','STOPPED') AND p.closed_at >= FROM_UNIXTIME(UNIX_TIMESTAMP()-14*86400) GROUP BY eq_bucket ORDER BY eq_bucket LIMIT 10;